s=s.replace("""  /** Retire the person from a date; a date left blank takes the sheet's today. */""","""  /** Cancel the person's last statement (a steward only): the claims it bound are live again. */
  protected async unstate(p: Person): Promise<void> {
    if (this.stating) return;
    this.personError.set(null);
    this.patronError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const headers = { 'X-User': this.session.user() ?? '' };
    this.stating = true;
    try {
      const saved = await firstValueFrom(
        this.http.delete<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${p.id}/statement`, {
          headers,
        }),
      );
      if (this.session.sheet() !== sheet) return;
      this.replace(saved);
    } catch {
      if (this.session.sheet() !== sheet) return;
      this.personError.set({
        id: p.id,
        message: 'Could not cancel the statement: only a steward can, and only a statement that was taken.',
      });
    } finally {
      this.stating = false;
    }
  }

  /** Retire the person from a date; a date left blank takes the sheet's today. */""",1)
open(p,'w').write(s)
