    /** Fix the period's due-totals as of the end of its last day and close it, or soft-close it. */
    private void fix(String sheetId, String user, Period period, boolean auto, boolean soft) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, p -> p));
        RateTable table = rates.table(sheetId);
        Map<Long, BigDecimal> totals = new HashMap<>();
        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> period.contains(c.getDate())
                        && Dues.countsAsOf(c, byId.get(c.getPersonId())::heldOn, table.today(), period.getToDate()))
                .forEach(c -> {
                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
                    if (due != null) {
                        totals.merge(c.getPersonId(), due, BigDecimal::add);
                    }
                });
        totals.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
        period.close(totals, soft);
        BigDecimal total = period.getClosedTotal().setScale(2, RoundingMode.HALF_UP);
        periods.flush();
        events.publishEvent(new PeriodClosed(sheetId, user, period.getName(), total, auto, soft));
    }

 * added after that day. */
export function statusAsOf(c: Claim, day: string): ClaimStatus | undefined {
  let status: ClaimStatus | undefined;
  for (const l of c.log) if (l.on <= day) status = l.status;
  return status;
}

/** Per period id, the person's due-total for it: the dues as shown now of their claims dated in it that counted
 * (OPEN, PENDING or SETTLED) at the end of its last day, added up, or once closed or soft-closed the figure fixed then (0.00
 * for a person added later); an unbound OPEN claim dated within a hold of its person counts in none, nor does
 * a deferred claim. */
export function personPeriodTotals(periods: Period[], person: PersonWithClaims): Record<number, string> {
  const totals: Record<number, number> = {};
  for (const p of periods) totals[p.id] = 0;
  for (const c of person.claims) {
    if (c.due === null || heldOut(c, person.holds) || c.deferred) continue;
    const period = periodOf(periods, c.date);
    if (!period || isFixed(period)) continue;
    const status = statusAsOf(c, period.to);
    if (status === 'OPEN' || status === 'PENDING' || status === 'SETTLED') totals[period.id] += cents(c.due);
  }
  const shown: Record<number, string> = {};
  for (const p of periods) {
    shown[p.id] = isFixed(p) ? (p.personTotals?.[person.id] ?? '0.00') : (totals[p.id] / 100).toFixed(2);
  }
  return shown;
}

/** Per period id, its due-total: the people's due-totals for it, added up. */
export function periodDueTotals(periods: Period[], people: PersonWithClaims[]): Record<number, string> {
  const totals: Record<number, number> = {};
  for (const p of periods) totals[p.id] = 0;
  for (const person of people) {
    const figures = personPeriodTotals(periods, person);
    for (const p of periods) totals[p.id] += cents(figures[p.id]);
  }
  const shown: Record<number, string> = {};
  for (const p of periods) shown[p.id] = (totals[p.id] / 100).toFixed(2);
  return shown;
}

